// One output item per LLM call found in the fetched executions.
const settings = $('Set configuration').first().json;
const prices = typeof settings.pricesPer1M === 'string'
  ? JSON.parse(settings.pricesPer1M)
  : settings.pricesPer1M || {};

// Exact model name first, then the longest matching prefix
// ("gpt-4o-mini-2024-07-18" uses the "gpt-4o-mini" price).
function priceFor(model) {
  if (prices[model]) return prices[model];
  const key = Object.keys(prices)
    .filter((k) => model.startsWith(k))
    .sort((a, b) => b.length - a.length)[0];
  return key ? prices[key] : null;
}

const rows = [];
for (const item of $input.all()) {
  const ex = item.json;
  if (ex.workflowId === $workflow.id) continue; // skip this logger
  if (!ex.stoppedAt) continue; // still running, picked up next time

  const runData = (ex.data && ex.data.resultData && ex.data.resultData.runData) || {};
  const nodes = (ex.workflowData && ex.workflowData.nodes) || [];

  for (const [nodeName, runs] of Object.entries(runData)) {
    runs.forEach((run, runIndex) => {
      // Chat model sub-nodes write their output on the ai_languageModel connection.
      const out = run.data && run.data.ai_languageModel && run.data.ai_languageModel[0] && run.data.ai_languageModel[0][0];
      if (!out || !out.json) return;
      const usage = out.json.tokenUsage || out.json.tokenUsageEstimate;
      if (!usage) return;

      const input = run.inputOverride && run.inputOverride.ai_languageModel && run.inputOverride.ai_languageModel[0] && run.inputOverride.ai_languageModel[0][0];
      const opts = (input && input.json && input.json.options) || {};
      const node = nodes.find((n) => n.name === nodeName) || {};
      const p = node.parameters || {};
      const model = String(
        opts.model || opts.modelName || opts.model_name ||
        (p.model && p.model.value) || p.model || p.modelName || 'unknown',
      );

      const promptTokens = usage.promptTokens || 0;
      const completionTokens = usage.completionTokens || 0;
      const price = priceFor(model);
      const costUsd = price
        ? Math.round(((promptTokens * price.input + completionTokens * price.output) / 1e6) * 1e8) / 1e8
        : null;

      rows.push({
        json: {
          callKey: `${ex.id}:${nodeName}:${runIndex}`,
          executionId: String(ex.id),
          workflowId: ex.workflowId,
          workflowName: (ex.workflowData && ex.workflowData.name) || '',
          nodeName,
          model,
          promptTokens,
          completionTokens,
          totalTokens: usage.totalTokens || promptTokens + completionTokens,
          estimated: !out.json.tokenUsage,
          costUsd,
          executionStatus: ex.status || '',
          finishedAt: ex.stoppedAt,
        },
      });
    });
  }
}
return rows;

// Sums today's LLM spend per workflow and returns the ones over budget.
const settings = $('Set configuration').first().json;
const overrides = typeof settings.budgetOverrides === 'string'
  ? JSON.parse(settings.budgetOverrides || '{}')
  : settings.budgetOverrides || {};

const spend = {};
for (const row of $input.all()) {
  const r = row.json;
  if (!r.workflowId) continue;
  const s = (spend[r.workflowId] = spend[r.workflowId] || { name: r.workflowName, usd: 0, calls: 0, unpriced: 0 });
  s.calls += 1;
  if (typeof r.costUsd === 'number') s.usd += r.costUsd;
  else s.unpriced += 1;
}

// Alert once per workflow per day. Static data is kept between production runs.
const memory = $getWorkflowStaticData('global');
const today = $now.toFormat('yyyy-MM-dd');
if (memory.alertDay !== today) {
  memory.alertDay = today;
  memory.alerted = {};
}

const result = [];
for (const [workflowId, s] of Object.entries(spend)) {
  if (workflowId === $workflow.id) continue;
  const budget = Number(overrides[workflowId] ?? settings.dailyBudgetUsd);
  if (!(s.usd > budget) || memory.alerted[workflowId]) continue;
  memory.alerted[workflowId] = true;

  const action = settings.pauseOverBudget ? 'It has been unpublished.' : 'It is still running.';
  const unpriced = s.unpriced ? ` ${s.unpriced} call(s) had no price in the table and are not counted.` : '';
  result.push({
    json: {
      workflowId,
      workflowName: s.name,
      spendUsd: Math.round(s.usd * 10000) / 10000,
      budgetUsd: budget,
      calls: s.calls,
      message: `LLM budget exceeded: "${s.name}" (id ${workflowId}) spent $${s.usd.toFixed(4)} today, budget $${budget}, ${s.calls} call(s). ${action}${unpriced}`,
    },
  });
}
return result;
